import{_ as t,a as e,b as i,c as o,d as r,e as n,f as l,g as s,h as c,i as d}from"./chunks/CAL11.DuBx0sYj.js";import{_ as p}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as h}from"./chunks/BDM.scaBLLhv.js";import{_ as b,o as m,c as u,a3 as g}from"./chunks/framework.g9mfNVRQ.js";const B=JSON.parse('{"title":"Calibrate","description":"","frontmatter":{},"headers":[],"relativePath":"calibrate/calibrate.md","filePath":"calibrate/calibrate.md"}'),y={name:"calibrate/calibrate.md"};function f(w,a,v,x,_,k){return m(),u("div",null,[...a[0]||(a[0]=[g('<div class="warning custom-block"><p class="custom-block-title">Calibration</p><p>Never blindly trust a glucose sensor: regularly verify the readings with a blood test.<br> A flat line (same number) is <strong>never</strong> a good sign.</p></div><h3 id="general-considerations" tabindex="-1">General considerations <a class="header-anchor" href="#general-considerations" aria-label="Permalink to &quot;General considerations&quot;">​</a></h3><p>Calibration is key to CGM measurement accuracy. Always use a trusted glucometer and make sure you put yourself in the best conditions to have the most accurate blood reading when calibrating.</p><p>Some of the most important prerequisites are:</p><ol><li><strong>Stable BG.</strong> Never calibrate when BG is rising or falling rapidly.</li><li><strong>In range (important for Libre initial calibration).</strong> Try to perform your calibrations when BG is within normal range (80-180 mg/dl or 5-10 mmol/l).</li><li><strong>Don&#39;t overcalibrate.</strong> Better a few accurate ones than too many: you will most probably confuse xDrip. For G6, G7, 1, 1+ use the vendor recommendations.</li></ol><h3 id="native-and-xdrip-algorithms" tabindex="-1">Native and xDrip algorithms <a class="header-anchor" href="#native-and-xdrip-algorithms" aria-label="Permalink to &quot;Native and xDrip algorithms&quot;">​</a></h3><p>xDrip can provide its own calibration algorithms for sensors sending raw data.</p><p>G6, G7, 1, 1+ native calibration means that xDrip will not use its algorithm but will send calibration values to the transmitter and let it handle it with its own proprietary algorithm.</p><p>Libre 1, 14 Days, Pro, 2 (EU) and 2+ (EU) sensors only send raw data, and will need either xDrip calibration or an external calibration plugin called <a href="./../use/OOP.html">out of process algorithm</a> (short OOP).</p><p>Libre 2 patched app will use its own proprietary algorithm (an old version though).</p><table tabindex="0"><thead><tr><th>Sensor</th><th>xDrip calibration</th><th>Native calibration</th></tr></thead><tbody><tr><td>G6 rebatteried</td><td>Available</td><td>Available</td></tr><tr><td>G6, G7, 1, 1+</td><td>Not available</td><td>Mandatory</td></tr><tr><td>Libre 1</td><td>Mandatory</td><td>OOP1 (obsolete)</td></tr><tr><td>Libre 2 EU patched app</td><td>Limited offset (see below)</td><td>By design</td></tr><tr><td>Libre 2/2+ EU, Libre 14 days US</td><td><a href="./../use/OOP.html#oop2">Optional</a></td><td>OOP2</td></tr></tbody></table><h5 id="libre-2-patched-app" tabindex="-1">Libre 2 patched app <a class="header-anchor" href="#libre-2-patched-app" aria-label="Permalink to &quot;Libre 2 patched app&quot;">​</a></h5><p>When using the patched app, you can calibrate but correction is applied as an offset with maximum values between -40 mg/dl and +20 mg/dL [-2,2 mmol/l and +1,1 mmol/l]. Calibrations failing these criteria will be <strong>ignored</strong>.</p><h3 id="xdrip-calibration-settings" tabindex="-1">xDrip calibration settings <a class="header-anchor" href="#xdrip-calibration-settings" aria-label="Permalink to &quot;xDrip calibration settings&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">xDrip calibration only</p><p>The information below is relevant to xDrip calibration.<br> For G6/G7/1/1+ native mode see <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">here</a>.</p></div><p>Before calibrating check your <a href="./advancedcal.html">settings</a>.</p><p>One thing you want to enable is <a href="./../use/lesscommon.html#show-data-tables">data tables</a> in the main menu. This will really help understanding when things go wrong.</p><h3 id="first-calibration" tabindex="-1">First calibration <a class="header-anchor" href="#first-calibration" aria-label="Permalink to &quot;First calibration&quot;">​</a></h3><p>If your sensor requires calibrations, after connecting it to xDrip and receiving three values you should see this request:</p><div class="admonition xdripitem"><p class="admonition-title">Calibrate Sensor?</p><p> We have some readings!</p><p> Next, we need the first calibration blood test.</p><p> Ready to calibrate now?</p><p> NO    <span style="background-color:white;color:black;"> CALIBRATE </span></p></div><p>Two initial calibration values are historical from G4. If you want to use that correctly: make two different measurements (two strips), this is a recommended approach. If you usually insert the same value you might want to make it a default <a href="./advancedcal.html#calibrations">here</a>.</p><div class="admonition xdrip"><p class="admonition-title">☰ Initial Calibration</p><p> <u>Enter First BG Value</u><br>  <u>Enter Second BG Value</u></p><p> <small>In order to get started, please perform one or two finger prick tests and enter the values here!</small></p></div><p>If you&#39;re using native calibration, the value will be sent to the transmitter for processing.</p><p>If you&#39;re using xDrip calibration, this value will be processed 10 minutes later to make sure to compensate for all physiological and chemical delays of the CGM measurement, <strong>this is why it&#39;s extremely important to calibrate at stable BG</strong>.</p><p>Let&#39;s look graphically at what will happen on the main view:</p><ol><li>First reading (brought to calibration value)</li><li>Second reading (brought to calibration value)</li><li>Not visible yet but it&#39;s the third reading. The actual value when you calibrated</li><li>Next reading in 5 minutes</li><li>Next reading in 10 minutes and the calibration point (that will be used in 10 minutes)</li></ol><img src="'+t+'"><p>If your BG remained stable during this time you should see it go through the calibration point.</p><img src="'+e+'"><p>Looking into your calibration data table you will see new entries corresponding to raw BG measurements used to define the calibration:</p><ol><li>This is the value you entered (converted if necessary to mg/dl)</li><li>Same value but in the unit you use with xDrip (here in mg/dl but will show also in mmol/l)</li><li>Raw BG from the sensor</li><li>Calculated slope and intercept</li><li>Effective calibration date and time (that is actual + 10 minutes) and corresponding raw BG date and time</li><li>There are two sets of raw data measurement for one calibration: one lower, one higher</li></ol><img src="'+i+'" style="zoom:75%;"><p>Your calibration graph will now be something like this.<br> Depending on the difference between blood samples and the variability of current BG, slope might not be exactly 1.</p><img src="'+o+'" style="zoom:75%;"><h3 id="successive-calibrations" tabindex="-1">Successive calibrations <a class="header-anchor" href="#successive-calibrations" aria-label="Permalink to &quot;Successive calibrations&quot;">​</a></h3><p>For safety reasons you will regularly check your real BG value, at least once per day because you can&#39;t blindly trust a sensor. Enter these blood tests as <a href="./../use/mainUI.html#treatments">treatments</a>.<br> In order to have BG values that are not varying too rapidly, you shouldn&#39;t calibrate when you have carbs or insulin active at that time.</p><div class="info custom-block"><p class="custom-block-title">Frequency</p><p>Unless expressly required by your sensor do not calibrate systematically when performing a blood test.<br> For Libre sensors, do not necessarily calibrate if difference is less than 15%.</p></div><p><strong>Don&#39;t overcalibrate</strong>, you can perform as many blood checks as you want, enter them as treatments in xDrip but add calibrations with extra care.</p><p>On your calibration graph you will see active calibration points in blue and old or invalid ones in grey.</p><img src="'+r+'" style="zoom:75%;"><p>If you see, at stable BG, comparing xDrip value 10 minutes after your blood test, that the value differs too much, you will add another calibration point.</p><p>Since BG trends often are difficult to forecast, you can use a trick:</p><ul><li>Check Use Treatment BG Values is not set to Never Use Them in <a href="./advancedcal.html">Advanced Calibrations</a>.</li><li>Enter your blood test as a treatment.</li></ul><img src="'+n+'" style="zoom:75%;"><ul><li>Wait 10 minutes and decide if it would have been a good time to calibrate (stable enough).</li></ul><img src="'+l+'" style="zoom:75%;"><ul><li>If it was, touch your treatment (the new BG test read and white square dot on the graph) and make it a calibration.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Blood Test Action</p><p> What would you like to do?</p><p> NOTHING DELETE   <span style="background-color:white;color:black;"> CALIBRATE </span></p></div><p>You now have another calibration point.</p><img src="'+s+'" style="zoom:75%;"><h3 id="disable-a-calibration" tabindex="-1">Disable a calibration <a class="header-anchor" href="#disable-a-calibration" aria-label="Permalink to &quot;Disable a calibration&quot;">​</a></h3><p>It might happen that a calibration point is clearly bad and you want to delete it.</p><p>Open the Calibration Data Table and <strong>long touch</strong> the calibration you want to disable.</p><img src="'+c+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Disable this calibration?</p><p>Flagged calibrations will no longer have an effect.</p><p>   NO    <span style="background-color:white;color:black;"> YES </span></p></div><p>It will show in red and will not be used for calculation anymore.</p><img src="'+d+'" style="zoom:75%;"><h3 id="reset-all-calibrations" tabindex="-1">Reset all calibrations <a class="header-anchor" href="#reset-all-calibrations" aria-label="Permalink to &quot;Reset all calibrations&quot;">​</a></h3><p>This method only applies to sensors supporting xDrip calibration.</p><p><strong>Do not use it for native calibration only sensors (G6 new, G7, 1, 1+ etc.).</strong></p><p>The fastest way to restart calibration from scratch (Initial Calibration) when it becomes clear that the current ones are wrong, or if you don&#39;t have data after calibrating is to reset all calibrations.</p><p>From the main menu, Stop Sensor.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+p+'" style="zoom:75%;"></p><p> Stop Sensor</p></div><p><strong>Do not stop sensor</strong>: only reset all calibrations.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+h+'" style="zoom:75%;"> Stop Sensor <span class="symbol"></span></p><p> Only stop your sensor when you actually plan to remove it, otherwise leave it running!</p><p>       <span style="background-color:white;color:black;"> DON&#39;T STOP, JUST RESET ALL CALIBRATIONS </span></p></div><div class="admonition xdripitem"><p class="admonition-title">Are you sure?</p><p> Do you want to delete and reset the calibrations for this sensor?</p><p>       NO    <span style="background-color:white;color:black;"> YES </span></p></div><p>xDrip will bring you back to <a href="#first-calibration">initial calibration</a>. Make sure you perform this action at stable BG, when in range.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',69)])])}const I=b(y,[["render",f]]);export{B as __pageData,I as default};
